//! PostgreSQL 18 operators from [`pg_operator.dat`](https://github.com/postgres/postgres/blob/REL_18_STABLE/src/include/catalog/pg_operator.dat), with stored `pg_type` names, exact implementing `pg_proc` signatures, commutator and negator symbols, the hash and merge flags, and the restriction and join estimators.

use alloc::borrow::Cow;

use super::{postgres_catalog::CatalogName, postgres_operator::PostgresCatalogOperator};
use crate::traits::OperatorKind;

/// A `pg_catalog` name a row holds, `_` for none.
macro_rules! name {
    (_) => {
        None
    };
    ($name:literal) => {
        Some(CatalogName::in_pg_catalog(Cow::Borrowed($name), false))
    };
}

/// Builds one row from stored `pg_operator`, `pg_type` and `pg_proc` names,
/// all in `pg_catalog`, `_` marking an absent left operand, link or
/// estimator.
macro_rules! operator {
    (@kind _) => {
        OperatorKind::Prefix
    };
    (@kind $left:literal) => {
        OperatorKind::Binary
    };
    (
        $name:literal, $left:tt, $right:literal, $result:literal, $function:literal,
        $commutator:tt, $negator:tt, $hashes:literal, $merges:literal, $restrict:tt, $join:tt
    ) => {
        PostgresCatalogOperator {
            target: CatalogName::in_pg_catalog(Cow::Borrowed($name), false),
            kind: operator!(@kind $left),
            left: name!($left),
            right: CatalogName::in_pg_catalog(Cow::Borrowed($right), false),
            result: name!($result),
            implementation: name!($function),
            commutator: name!($commutator),
            negator: name!($negator),
            can_hash: $hashes,
            can_merge: $merges,
            restriction_estimator: name!($restrict),
            join_estimator: name!($join),
        }
    };
}

